        c = new MONEY_BOX();
    }

    function _run(uint256 val, address log) internal {
        bool reverted1;
        bool reverted2;
        try c.Initialized() {} catch { return; }
        try c.SetMinSum(val) { reverted1 = false; } catch { reverted1 = true; }
        try c.SetLogFile(log) { reverted2 = false; } catch { reverted2 = true; }
        assertTrue(reverted1 && reverted2);
    }

    function testFuzz_run(uint256 val, address log) public {
